# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OSMANLI DEVLETİ\'Nİ CİHAN DEVLETİ YAPAN TEMEL POLİTİKALAR</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Siyasi ve Askerî Etkenler</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Stratejik coğrafi konum (Uç</text>\n  <text x="38" y="114" font-size="11" fill="#334155">  beyliği: Söğüt ve Domaniç).</text>\n  <text x="38" y="138" font-size="11" font-weight="bold" fill="#1e40af">• Gaza ve Cihat Anlayışı:</text>\n  <text x="38" y="154" font-size="11" fill="#334155">  İslam\'ı koruma ve yayma ülküsü.</text>\n  <text x="38" y="178" font-size="11" fill="#334155">• Güçlü merkezî otorite ve</text>\n  <text x="38" y="194" font-size="11" fill="#334155">  disiplinli düzenli ordu sistemi</text>\n  <text x="38" y="210" font-size="11" fill="#334155">  (Tımarlı Sipahi + Kapıkulu).</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. İskân (Yerleştirme)</text>\n  <text x="258" y="98" font-size="11" fill="#334155">• Balkanlarda fethedilen yerlere</text>\n  <text x="258" y="114" font-size="11" fill="#334155">  Anadolu\'dan konargöçer</text>\n  <text x="258" y="130" font-size="11" fill="#334155">  Türkmenlerin yerleştirilmesi.</text>\n  <text x="258" y="154" font-size="11" font-weight="bold" fill="#166534">• Amaç ve Sonuçları:</text>\n  <text x="258" y="172" font-size="11" fill="#334155">  Fetihler kalıcı oldu, Balkanlar</text>\n  <text x="258" y="188" font-size="11" fill="#334155">  Türkleşti ve boş araziler</text>\n  <text x="258" y="204" font-size="11" fill="#334155">  tarıma kazandırıldı.</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. İstimalet (Gönül Alma)</text>\n  <text x="478" y="98" font-size="11" fill="#334155">• Fethedilen yerlerdeki halka</text>\n  <text x="478" y="114" font-size="11" fill="#334155">  hoşgörü, adalet ve din-vicdan</text>\n  <text x="478" y="130" font-size="11" fill="#334155">  özgürlüğü tanınmasıdır.</text>\n  <text x="478" y="154" font-size="11" font-weight="bold" fill="#92400e">• Amaç ve Sonuçları:</text>\n  <text x="478" y="172" font-size="11" fill="#334155">  Can ve mal güvenliği sağlandı,</text>\n  <text x="478" y="188" font-size="11" fill="#334155">  vergi kolaylığı getirildi ve</text>\n  <text x="478" y="204" font-size="11" fill="#334155">  halkın devlete bağlılığı arttı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSKÂN VE İSTİMALET POLİTİKALARININ KARŞILAŞTIRMALI ANALİZİ</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İskân (Şenlendirme) Politikası İlkeleri</text>\n  <text x="44" y="100" font-size="11" fill="#334155">• Öncelikle konargöçer (Yörük/Türkmen) aileler</text>\n  <text x="44" y="116" font-size="11" fill="#334155">  seçilerek yerleşik hayata geçmeleri sağlandı.</text>\n  <text x="44" y="140" font-size="11" fill="#334155">• Aralarında anlaşmazlık olan ailelerden biri</text>\n  <text x="44" y="156" font-size="11" fill="#334155">  göç ettirilerek toplumsal barış korundu.</text>\n  <text x="44" y="180" font-size="11" fill="#334155">• Göç edenlere toprak, tohum ve geçici vergi</text>\n  <text x="44" y="196" font-size="11" fill="#334155">  muafiyeti verildi; geçerli sebep olmadan eski</text>\n  <text x="44" y="212" font-size="11" font-weight="bold" fill="#1e40af">  yerlerine dönmelerine izin verilmedi.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">İstimalet ve Millet Sistemi</text>\n  <text x="378" y="100" font-size="11.5" font-weight="bold" fill="#991b1b">• İstimalet (Gönül Kazanma):</text>\n  <text x="388" y="118" font-size="11" fill="#334155">Gayrimüslim halka baskı yapılmaması, ibadet</text>\n  <text x="388" y="134" font-size="11" fill="#334155">yerlerine dokunulmaması ve adaletle yönetim.</text>\n  <text x="378" y="162" font-size="11.5" font-weight="bold" fill="#991b1b">• Millet Sistemi:</text>\n  <text x="388" y="180" font-size="11" fill="#334155">Toplumu ırk veya etnik kökene göre değil,</text>\n  <text x="388" y="196" font-size="11" fill="#334155">din ve mezhep esasına göre yöneterek</text>\n  <text x="388" y="212" font-size="11" fill="#334155">kültürel çeşitliliği barış içinde yaşatma.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SOSYO-EKONOMİK GÜÇ: TIMAR SİSTEMİ, AHİLİK VE VAKIF KÜLTÜRÜ</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Tımar (Dirlik) Sistemi</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Devlete ait toprakların</text>\n  <text x="38" y="114" font-size="11" fill="#334155">  geliriyle atlı asker (Tımarlı</text>\n  <text x="38" y="130" font-size="11" fill="#334155">  Sipahi) yetiştirilmesidir.</text>\n  <text x="38" y="154" font-size="11" font-weight="bold" fill="#166534">• Faydaları:</text>\n  <text x="38" y="172" font-size="11" fill="#334155">  Toprak boş kalmaz, üretim</text>\n  <text x="38" y="188" font-size="11" fill="#334155">  sürer, hazineden para çıkmadan</text>\n  <text x="38" y="204" font-size="11" fill="#334155">  ordu ve güvenlik sağlanır.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Ahilik ve Toplumsal Destek</text>\n  <text x="258" y="98" font-size="11" fill="#334155">• Ahiyan-ı Rûm (Ahiler): Esnaf</text>\n  <text x="258" y="114" font-size="11" fill="#334155">  dayanışması, meslek eğitimi</text>\n  <text x="258" y="130" font-size="11" fill="#334155">  ve ticaret ahlakı sağladı.</text>\n  <text x="258" y="154" font-size="11" fill="#334155">• Gaziyan-ı Rûm (Alpler/Gaziler)</text>\n  <text x="258" y="172" font-size="11" fill="#334155">• Bacıyan-ı Rûm (Anadolu</text>\n  <text x="258" y="188" font-size="11" fill="#334155">  Kadınları) ve Abdalan-ı Rûm</text>\n  <text x="258" y="204" font-size="11" fill="#334155">  gönülleri fethetti.</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Vakıf Sistemi ve Ticaret</text>\n  <text x="478" y="98" font-size="11" fill="#334155">• Fethedilen şehirlerde cami,</text>\n  <text x="478" y="114" font-size="11" fill="#334155">  medrese, darüşşifa, imarethane,</text>\n  <text x="478" y="130" font-size="11" fill="#334155">  han ve köprüler inşa edildi.</text>\n  <text x="478" y="154" font-size="11" fill="#334155">• İpek ve Baharat yolları</text>\n  <text x="478" y="170" font-size="11" fill="#334155">  ile liman şehirleri alınarak</text>\n  <text x="478" y="188" font-size="11" font-weight="bold" fill="#92400e">  dünya ticaretinin kontrolü</text>\n  <text x="478" y="204" font-size="11" font-weight="bold" fill="#92400e">  sağlandı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
